#!/bin/bash
# Setup script for modern-web-app
# Generated by DevOps Project Generator v2.0.0

set -euo pipefail

# Colors for output
RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
NC='\033[0m' # No Color

# Logging functions
log_info() {
    echo -e "${GREEN}[INFO]${NC} $1"
}

log_warn() {
    echo -e "${YELLOW}[WARN]${NC} $1"
}

log_error() {
    echo -e "${RED}[ERROR]${NC} $1"
}

# Check prerequisites
check_prerequisites() {
    log_info "Checking prerequisites..."
    
    # Check Docker
    if ! command -v docker &> /dev/null; then
        log_error "Docker is not installed. Please install Docker first."
        exit 1
    fi
    
    # Check Docker Compose
    if ! command -v docker-compose &> /dev/null; then
        log_error "Docker Compose is not installed. Please install Docker Compose first."
        exit 1
    fi
    
    # Check kubectl if using Kubernetes
    if command -v kubectl &> /dev/null; then
        log_info "kubectl found"
    else
        log_warn "kubectl not found. Kubernetes deployment may not work."
    fi
    
    # Check Terraform if using infrastructure as code
    if command -v terraform &> /dev/null; then
        log_info "Terraform found"
    else
        log_warn "Terraform not found. Infrastructure as code may not work."
    fi
    
    log_info "Prerequisites check completed."
}

# Setup environment
setup_environment() {
    log_info "Setting up environment..."
    
    # Create .env file if it doesn't exist
    if [ ! -f .env ]; then
        if [ -f .env.example ]; then
            cp .env.example .env
            log_info "Created .env file from .env.example"
        else
            log_warn ".env.example not found. Creating basic .env file."
            cat > .env << EOF
PORT=8080
LOG_LEVEL=INFO
ENVIRONMENT=development
EOF
        fi
    else
        log_info ".env file already exists"
    fi
    
    # Create necessary directories
    mkdir -p logs
    mkdir -p data
    mkdir -p backups
    
    log_info "Environment setup completed."
}

# Build Docker images
build_images() {
    log_info "Building Docker images..."
    
    # Build main application
    docker build -t modern-web-app:latest .
    
    if [ $? -eq 0 ]; then
        log_info "Docker image built successfully"
    else
        log_error "Failed to build Docker image"
        exit 1
    fi
}

# Run initial tests
run_tests() {
    log_info "Running initial tests..."
    
    # Run unit tests
    docker run --rm modern-web-app:latest python -m pytest tests/ -v
    
    if [ $? -eq 0 ]; then
        log_info "Tests passed successfully"
    else
        log_warn "Some tests failed. Check the output above."
    fi
}

# Main setup function
main() {
    log_info "Starting setup for modern-web-app..."
    
    check_prerequisites
    setup_environment
    build_images
    run_tests
    
    log_info "Setup completed successfully!"
    log_info "You can now run the application with: make run"
}

# Run main function
main "$@"